#!/usr/bin/env python3
"""Generate Alacritty key bindings that turn Ctrl/Alt + Cyrillic letter into
the Ctrl/Alt + Latin key on the same physical position.

Helix (and other terminal programs) expects e.g. `Ctrl-f` for page-down.  In the
Russian layout the same physical key produces a Cyrillic character, and with
Ctrl held the terminal would otherwise send nothing usable.  These bindings make
`Ctrl-ф` behave exactly like `Ctrl-a`, `Alt-ф` like `Alt-a`, and so on.

The generated block is written into alacritty.toml between the markers:

    # >>> ru-keybindings (generated, do not edit) >>>
    ...
    # <<< ru-keybindings (generated, do not edit) <<<

Usage:  gen_ru_keybindings.py [alacritty.toml]
"""

from __future__ import annotations

import sys
from pathlib import Path

HERE = Path(__file__).resolve().parent
DEFAULT_CONFIG = HERE.parent / "alacritty.toml"

BEGIN = "# >>> ru-keybindings (generated, do not edit) >>>"
END = "# <<< ru-keybindings (generated, do not edit) <<<"

# Physical key -> (Latin, Cyrillic) for the Russian "winkeys" layout.
LETTERS = {
    "q": "й", "w": "ц", "e": "у", "r": "к", "t": "е", "y": "н", "u": "г",
    "i": "ш", "o": "щ", "p": "з",
    "a": "ф", "s": "ы", "d": "в", "f": "а", "g": "п", "h": "р", "j": "о",
    "k": "л", "l": "д",
    "z": "я", "x": "ч", "c": "с", "v": "м", "b": "и", "n": "т", "m": "ь",
}


def ctrl(latin: str) -> str:
    return "\\u%04x" % (ord(latin) & 0x1F)


def alt(latin: str) -> str:
    return "\\u001b" + latin


def binding(key: str, mods: str, chars: str) -> str:
    return (
        "[[keyboard.bindings]]\n"
        f'key = "{key}"\n'
        f'mods = "{mods}"\n'
        f'chars = "{chars}"\n'
    )


def build() -> str:
    parts = [
        BEGIN,
        "# Generated by scripts/gen_ru_keybindings.py -- do not edit by hand.",
        "# Ctrl/Alt + Cyrillic letter -> the Latin key on the same physical key,",
        "# so Helix receives the expected control codes / meta sequences.",
        "",
    ]
    for latin, ru in LETTERS.items():
        lo, up = ru, ru.upper()
        # Ctrl + key (exact modifiers, as Alacritty matches them exactly).
        parts.append(binding(lo, "Control", ctrl(latin)))
        parts.append(binding(up, "Control | Shift", ctrl(latin)))
        # Alt + key -> ESC + Latin (what Helix parses as Alt+LATIN).
        parts.append(binding(lo, "Alt", alt(latin)))
        parts.append(binding(up, "Alt | Shift", alt(latin.upper())))
    parts.append(END)
    parts.append("")
    return "\n".join(parts)


def write_config(config_path: Path, block: str):
    text = config_path.read_text(encoding="utf-8")
    if BEGIN in text and END in text:
        pre = text[: text.index(BEGIN)]
        post = text[text.index(END) + len(END) :]
        new = pre.rstrip() + "\n\n" + block.rstrip() + "\n" + post.lstrip("\n")
    else:
        new = text.rstrip() + "\n\n" + block
    config_path.write_text(new, encoding="utf-8")


def main():
    config_path = Path(sys.argv[1]) if len(sys.argv) > 1 else DEFAULT_CONFIG
    block = build()
    if len(sys.argv) > 2 and sys.argv[2] == "--stdout":
        sys.stdout.write(block)
        return
    write_config(config_path, block)
    print(f"updated {config_path}")


if __name__ == "__main__":
    main()
